	/**
	 * User enters either:
	 *   Status = 'Active'
	 * or:
	 *   [Status = 'Active']
	 *
	 * We normalize to bracket form (or empty).
	 */
	private static String normalizeMainXpathConstraint(String raw) {
		String c = raw == null ? "" : raw.trim();
		if (c.isEmpty()) return "";
		if (!c.startsWith("[")) c = "[" + c;
		if (!c.endsWith("]")) c = c + "]";
		return c;
	}

