	/**
	 * ✅ NORMALIZE STEP ORDER
	 *
	 * Goal: keep the chain as:
	 *   MailTemplate (anchor) -> MainEntity -> ... -> Attribute
	 *
	 * Your runtime starts from MainEntity, so MailTemplate will naturally be skipped.
	 * But if the stored chain comes in reversed, resolution breaks (as you saw in logs).
	 */
	private static void normalizeStepOrder(TokenPlan p) {
		if (p == null || p.steps == null || p.steps.size() < 2) return;

		StepPlan first = p.steps.get(0);
		StepPlan last  = p.steps.get(p.steps.size() - 1);

		boolean lastIsMailTemplate = ANCHOR_MAILTEMPLATE_TYPE.equals(safe(last.stepMxObjectTypeCompleteName));
		boolean looksReversedByShape = isAttributeStep(first) && isReferenceStep(last); // Attribute ... Reference
		boolean needsReverse = lastIsMailTemplate || looksReversedByShape;

		if (needsReverse) {
			LOG.debug("normalizeStepOrder: reversing steps for tokenPattern='" + safe(p.fullPattern) + "'"
				+ " (lastIsMailTemplate=" + lastIsMailTemplate
				+ ", looksReversedByShape=" + looksReversedByShape + ")");
			List<StepPlan> rev = new ArrayList<>();
			for (int i = p.steps.size() - 1; i >= 0; i--) {
				rev.add(p.steps.get(i));
			}
			p.steps = rev;
		} else {
			LOG.debug("normalizeStepOrder: steps order looks OK for tokenPattern='" + safe(p.fullPattern) + "'");
		}
	}

	/**
	 * Tries to turn an MxModelReflection association complete name into something that
	 * Core.retrieveByPath() can actually use for the CURRENT object's runtime type.
	 */
	private static String resolveAssocNameForObject(IContext context, IMendixObject current, String rawAssoc) {
		String raw = safe(rawAssoc).trim();
		if (raw.isEmpty()) return "";

		IMetaObject mo = Core.getMetaObject(current.getType());
		String currentModule = moduleOf(current.getType());

		List<String> candidates = new ArrayList<>();

		// 1) raw as-is
		candidates.add(raw);

		// 2) if contains '/', try parts
		if (raw.contains("/")) {
			for (String part : raw.split("/")) {
				String partTrim = safe(part).trim();
				if (!partTrim.isEmpty()) candidates.add(partTrim);
			}
		}

		// 3) last segment like "Intern_University"
		String last = lastSegment(raw);
		if (!last.isEmpty()) {
			candidates.add(last);
			if (!currentModule.isEmpty()) {
				candidates.add(currentModule + "." + last);
			}
		}

		// de-dup preserve order
		List<String> uniq = new ArrayList<>();
		for (String c : candidates) {
			String cc = safe(c).trim();
			if (cc.isEmpty()) continue;
			if (!uniq.contains(cc)) uniq.add(cc);
		}

		LOG.debug("resolveAssocNameForObject: currentType=" + current.getType()
			+ " rawAssoc='" + rawAssoc + "' candidates=" + uniq);

		for (String cand : uniq) {
			boolean ok = metaAssociationExists(mo, cand);
			LOG.debug("  metaAssociationExists? '" + cand + "' => " + ok);
			if (ok) {
				LOG.debug("  ✅ resolved association name='" + cand + "'");
				return cand;
			}
		}

		LOG.debug("  ❌ could not resolve association name for rawAssoc='" + rawAssoc + "' currentType=" + current.getType());
		return "";
	}

	private static boolean metaAssociationExists(IMetaObject mo, String assocName) {
		if (mo == null) return false;

		String name = safe(assocName).trim();
		if (name.isEmpty()) return false;

		// exact
		if (metaAssociationExistsExact(mo, name)) return true;

		// last segment
		String last = lastSegment(name);
		if (!last.isEmpty() && !last.equals(name)) {
			if (metaAssociationExistsExact(mo, last)) return true;
		}

		return false;
	}

	private static boolean metaAssociationExistsExact(IMetaObject mo, String name) {
		try {
			IMetaAssociation a = mo.getMetaAssociationChild(name);
			if (a != null) return true;
		} catch (Exception ignored) { }

		try {
			IMetaAssociation a = mo.getMetaAssociationParent(name);
			if (a != null) return true;
		} catch (Exception ignored) { }

		try {
			for (IMetaAssociation a : mo.getMetaAssociationsChild()) {
				if (a != null && name.equals(safe(a.getName()))) return true;
			}
		} catch (Exception ignored) { }

		try {
			for (IMetaAssociation a : mo.getMetaAssociationsParent()) {
				if (a != null && name.equals(safe(a.getName()))) return true;
			}
		} catch (Exception ignored) { }

		return false;
	}

	private static class StepPlan {
		String stepMxObjectTypeCompleteName;
		String associationCompleteName;
		String xpathConstraint;
		String attributeName;
	}

	private static class TokenPlan {
		Token token;
		String fullPattern;

		String mailTargetAttributeName;
		String tokenTargetMxObjectTypeCompleteName;

		List<StepPlan> steps = new ArrayList<>();
	}

	private static TokenPlan buildPlan(IContext context, Token token) {
		TokenPlan p = new TokenPlan();
		p.token = token;
		p.fullPattern = buildFullPattern(token);

		p.tokenTargetMxObjectTypeCompleteName = resolveTokenTargetMxObjectTypeCompleteName(context, token);
		p.mailTargetAttributeName = resolveTokenMailTargetAttributeName(context, token);

		List<SelectionStep> all = loadSteps(context, token);
		if (all == null || all.isEmpty()) {
			LOG.debug("buildPlan: tokenId=" + token.getMendixObject().getId().toLong() + " has 0 SelectionSteps.");
			return p;
		}

		SelectionStep root = findRootStep(context, all);
		SelectionStep cur = root;

		while (cur != null) {
			StepPlan sp = new StepPlan();

			sp.xpathConstraint = safe(cur.getXpathString());
			sp.stepMxObjectTypeCompleteName = resolveStepMxObjectTypeCompleteName(context, cur);

			MxObjectReference mxRef = getStepMxRef(context, cur);
			sp.associationCompleteName = mxRef == null ? "" : safe(mxRef.getCompleteName());

			sp.attributeName = resolveStepMemberAttributeName(context, cur);

			p.steps.add(sp);
			cur = getNextStep(context, cur);
		}

		// ✅ HERE is the fix:
		normalizeStepOrder(p);

		return p;
	}

	private static void applyTokenPlan(
		IContext context,
		TokenPlan plan,
		Mail mailProxy,
		IMendixObject mainTargetObj,
		String mainEntityName
	) {
		if (plan == null) return;
		if (plan.fullPattern == null || plan.fullPattern.isEmpty()) return;
		if (plan.mailTargetAttributeName == null || plan.mailTargetAttributeName.isEmpty()) return;

		final boolean deterministic = safe(plan.tokenTargetMxObjectTypeCompleteName).equals(mainEntityName);

		LOG.debug("applyTokenPlan: mailId=" + mailProxy.getMendixObject().getId().toLong()
			+ " mainTarget=" + mainTargetObj.getType() + "(" + mainTargetObj.getId().toLong() + ")"
			+ " pattern='" + plan.fullPattern + "'"
			+ " targetField=" + plan.mailTargetAttributeName
			+ " tokenTargetType=" + safe(plan.tokenTargetMxObjectTypeCompleteName)
			+ " mainType=" + mainEntityName
			+ " deterministic=" + deterministic);

		if ("Subject".equals(plan.mailTargetAttributeName)) {
			LOG.debug("  token present in Subject? " + safe(mailProxy.getSubject()).contains(plan.fullPattern));
		} else if ("Message".equals(plan.mailTargetAttributeName)) {
			LOG.debug("  token present in Message? " + safe(mailProxy.getMessage()).contains(plan.fullPattern));
		}

		ResolutionResult rr = resolveValue(context, plan, mainTargetObj, deterministic);
		LOG.debug("  resolveValue: shouldReplace=" + rr.shouldReplace + " replacement='" + safe(rr.replacement) + "'");

		if (!rr.shouldReplace) return;

		if ("Subject".equals(plan.mailTargetAttributeName)) {
			String cur = safe(mailProxy.getSubject());
			String next = cur.replace(plan.fullPattern, rr.replacement);
			mailProxy.setSubject(next);
			LOG.debug("  replaced Subject changed? " + (!cur.equals(next)));
		} else if ("Message".equals(plan.mailTargetAttributeName)) {
			String cur = safe(mailProxy.getMessage());
			String next = cur.replace(plan.fullPattern, rr.replacement);
			mailProxy.setMessage(next);
			LOG.debug("  replaced Message changed? " + (!cur.equals(next)));
		}
	}

	private static class ResolutionResult {
		boolean shouldReplace;
		String replacement;
	}

	private static ResolutionResult resolveValue(IContext context, TokenPlan plan, IMendixObject startObj, boolean deterministic) {
		ResolutionResult rr = new ResolutionResult();
		rr.shouldReplace = false;
		rr.replacement = "";

		if (plan.steps == null || plan.steps.isEmpty()) {
			if (deterministic) {
				throw new RuntimeException("Main-group token '" + plan.fullPattern + "' has no SelectionSteps configured.");
			}
			return rr;
		}

		IMendixObject current = startObj;

		// Skip prefix steps until expectedType matches current runtime type
		int i = 0;
		while (i < plan.steps.size()) {
			String expectedType = safe(plan.steps.get(i).stepMxObjectTypeCompleteName);
			if (expectedType.isEmpty() || expectedType.equals(current.getType())) {
				break;
			}
			i++;
		}

		LOG.debug("resolveValue: startType=" + startObj.getType()
			+ " startId=" + startObj.getId().toLong()
			+ " startAtStepIndex=" + i
			+ " stepsTotal=" + plan.steps.size());

		if (i >= plan.steps.size()) {
			LOG.debug("resolveValue: could not find matching starting step for currentType=" + current.getType());
			return rr;
		}

		for (; i < plan.steps.size(); i++) {
			StepPlan sp = plan.steps.get(i);

			String expected = safe(sp.stepMxObjectTypeCompleteName);
			LOG.debug("  step#" + i + " currentType=" + current.getType()
				+ " expectedType=" + expected
				+ " assocRaw='" + safe(sp.associationCompleteName) + "'"
				+ " attrRaw='" + safe(sp.attributeName) + "'"
				+ " xpath='" + safe(sp.xpathConstraint) + "'");

			if (!expected.isEmpty() && !expected.equals(current.getType())) {
				if (deterministic) {
					LOG.debug("    mismatch but deterministic => skipping step");
					continue;
				}
				LOG.debug("    mismatch and NOT deterministic => stop (no replace)");
				return rr;
			}

			String assocRaw = safe(sp.associationCompleteName);
			if (!assocRaw.isEmpty()) {

				String assoc = resolveAssocNameForObject(context, current, assocRaw);

				if (assoc.isEmpty()) {
					if (deterministic) {
						throw new RuntimeException(
							"Main-group token '" + plan.fullPattern + "' has invalid association reference '" + assocRaw +
							"' for runtime type '" + current.getType() + "'."
						);
					}
					LOG.debug("    assoc resolve failed => stop (no replace)");
					return rr;
				}

				List<IMendixObject> candidates = Core.retrieveByPath(context, current, assoc);
				LOG.debug("    retrieveByPath assoc='" + assoc + "' count=" + (candidates == null ? 0 : candidates.size()));

				candidates = filterByOptionalXpath(context, candidates, safe(sp.xpathConstraint));
				LOG.debug("    after xpath filter count=" + (candidates == null ? 0 : candidates.size()));

				if (candidates == null || candidates.isEmpty()) {
					if (deterministic) {
						throw new RuntimeException("Main-group token '" + plan.fullPattern + "' resolved to 0 objects at association '" + assoc + "'.");
					}
					LOG.debug("    0 objects => stop (no replace)");
					return rr;
				}
				if (candidates.size() != 1) {
					if (deterministic) {
						throw new RuntimeException("Main-group token '" + plan.fullPattern + "' resolved to " + candidates.size() + " objects at association '" + assoc + "'.");
					}
					LOG.debug("    many objects (" + candidates.size() + ") => stop (no replace)");
					return rr;
				}

				current = candidates.get(0);
				LOG.debug("    moved to " + current.getType() + "(" + current.getId().toLong() + ")");
				continue;
			}

			String attr = safe(sp.attributeName);
			if (!attr.isEmpty()) {
				Object val = readAttributeSafely(context, current, attr);
				rr.shouldReplace = true;
				rr.replacement = val == null ? "" : val.toString();
				LOG.debug("    attribute resolved: '" + attr + "' => '" + rr.replacement + "'");
				return rr;
			}

			LOG.debug("    step had neither assoc nor attr => continue");
		}

		if (deterministic) {
			throw new RuntimeException("Main-group token '" + plan.fullPattern + "' did not reach an attribute step.");
		}
		LOG.debug("resolveValue: finished steps without attribute => no replace");
		return rr;
	}

	private static Object readAttributeSafely(IContext context, IMendixObject obj, String attributeName) {
		String attr = safe(attributeName).trim();
		if (attr.isEmpty()) {
			throw new RuntimeException("AttributeName is empty when trying to read a value from " + obj.getType());
		}

		int slash = attr.lastIndexOf('/');
		if (slash >= 0 && slash < attr.length() - 1) {
			attr = attr.substring(slash + 1);
		}

		int dot = attr.lastIndexOf('.');
		if (dot >= 0 && dot < attr.length() - 1) {
			attr = attr.substring(dot + 1);
		}

		try {
			return obj.getValue(context, attr);
		} catch (IllegalArgumentException ignored) {
		}

		try {
			IMetaObject mo = Core.getMetaObject(obj.getType());
			IMetaPrimitive mp = mo.getMetaPrimitive(attr);
			return obj.getValue(context, mp.getName());
		} catch (Exception e) {
			throw new RuntimeException(
				"No primitive attribute '" + attr + "' exists on object type '" + obj.getType() + "'. Original was '" + attributeName + "'.",
				e
			);
		}
	}

	private static List<IMendixObject> filterByOptionalXpath(IContext context, List<IMendixObject> candidates, String constraintRaw) {
		if (candidates == null || candidates.isEmpty()) return candidates;

		String c = constraintRaw == null ? "" : constraintRaw.trim();
		if (c.isEmpty()) return candidates;

		if (!c.startsWith("[")) c = "[" + c + "]";
		if (!c.endsWith("]")) c = c + "]";

		String type = candidates.get(0).getType();
		String xpath = "//" + type + c;

		final List<IMendixObject> filtered;
		try {
			filtered = Core.createXPathQuery(xpath).execute(context);
		} catch (RuntimeException e) {
			LOG.debug("filterByOptionalXpath: invalid xpath '" + xpath + "' => returning EMPTY");
			return new ArrayList<IMendixObject>();
		}

		if (filtered == null || filtered.isEmpty()) return new ArrayList<IMendixObject>();

		HashSet<Long> allowed = new HashSet<>();
		for (IMendixObject f : filtered) {
			allowed.add(f.getId().toLong());
		}

		List<IMendixObject> out = new ArrayList<>();
		for (IMendixObject cand : candidates) {
			if (allowed.contains(cand.getId().toLong())) out.add(cand);
		}
		return out;
	}

	private static List<SelectionStep> loadSteps(IContext context, Token token) {
		List<IMendixObject> stepObjs = Core.retrieveByPath(
			context,
			token.getMendixObject(),
			SelectionStep.MemberNames.SelectionStep_Token.toString()
		);

		List<SelectionStep> steps = new ArrayList<>();
		if (stepObjs != null) {
			for (IMendixObject so : stepObjs) {
				if (so != null) steps.add(SelectionStep.initialize(context, so));
			}
		}
		return steps;
	}

	private static SelectionStep findRootStep(IContext context, List<SelectionStep> steps) {
		Set<Long> childIds = new HashSet<>();
		for (SelectionStep s : steps) {
			List<IMendixObject> children = Core.retrieveByPath(
				context,
				s.getMendixObject(),
				SelectionStep.MemberNames.SelectionStep_SelectionStep.toString()
			);
			if (children != null) {
				for (IMendixObject child : children) {
					childIds.add(child.getId().toLong());
				}
			}
		}
		for (SelectionStep s : steps) {
			long id = s.getMendixObject().getId().toLong();
			if (!childIds.contains(id)) return s;
		}
		return steps.get(0);
	}

	private static SelectionStep getNextStep(IContext context, SelectionStep step) {
		List<IMendixObject> next = Core.retrieveByPath(
			context,
			step.getMendixObject(),
			SelectionStep.MemberNames.SelectionStep_SelectionStep.toString()
		);
		if (next == null || next.isEmpty()) return null;
		return SelectionStep.initialize(context, next.get(0));
	}

