	private static String resolveTokenMailTargetAttributeName(IContext context, Token token) {
		List<IMendixObject> targetMemberObjs = Core.retrieveByPath(
			context,
			token.getMendixObject(),
			Token.MemberNames.Token_MxObjectMember_Target.toString()
		);
		if (targetMemberObjs == null || targetMemberObjs.isEmpty()) return "";
		MxObjectMember mxMember = MxObjectMember.initialize(context, targetMemberObjs.get(0));

		String raw = safe(mxMember.getAttributeName());
		String last = normalizeMemberToLastSegment(raw);

		if (!"Subject".equals(last) && !"Message".equals(last)) {
			throw new RuntimeException("Token_MxObjectMember_Target must be MailTemplate.Subject or MailTemplate.Message, but was: " + raw);
		}
		return last;
	}

	private static String resolveTokenTargetMxObjectTypeCompleteName(IContext context, Token token) {
		List<IMendixObject> targetObjs = Core.retrieveByPath(
			context,
			token.getMendixObject(),
			Token.MemberNames.Token_Target.toString()
		);
		if (targetObjs == null || targetObjs.isEmpty()) return "";

		IMendixObject targetObj = targetObjs.get(0);

		List<IMendixObject> mxTypeObjs = Core.retrieveByPath(context, targetObj, "Halkbank_TokenUtility.Target_MxObjectType");
		if (mxTypeObjs == null || mxTypeObjs.isEmpty()) return "";

		MxObjectType mxType = MxObjectType.initialize(context, mxTypeObjs.get(0));
		return safe(mxType.getCompleteName());
	}

